      r.createdBody,
      contains('360'),
      reason: 'the timeout-minutes ceiling from daily-publish.yml',
    );
    expect(
      r.createdBody,
      isNot(contains('(no failed-step log available')),
      reason: 'the cancelled leg job log IS served per-job mid-run',
    );
