        },
        withWorkflowYaml: true,
        pathShims: const {'date': _bsdDateShim},
      );
      expect(
        r.createdBody,
        contains('5h59m53s'),
        reason:
            '05:17:00Z -> 11:16:53Z elapsed, BSD date included:\n'
            '${r.createdBody}',
      );
      expect(
        r.createdBody,
        isNot(contains('unknown elapsed')),
        reason: r.createdBody,
      );
    },
  );

